use crate::repository::{Database,rows,err};
use rusqlite::{Connection,OptionalExtension,params};
use serde_json::{Value,json};
fn tables(c:&Connection)->Result<(),String>{c.execute_batch("CREATE TABLE IF NOT EXISTS doctor_revisions(id INTEGER PRIMARY KEY REFERENCES doctors(id),revision INTEGER NOT NULL DEFAULT 1);CREATE TABLE IF NOT EXISTS study_signatures(study_id INTEGER PRIMARY KEY REFERENCES studies(id),doctor_id INTEGER NOT NULL,name TEXT NOT NULL);").map_err(err)}
fn freeze(c:&Connection)->Result<(),String>{tables(c)?;c.execute("INSERT OR IGNORE INTO study_signatures SELECT s.id,s.doctor_id,COALESCE(d.name,'') FROM studies s LEFT JOIN doctors d ON d.id=s.doctor_id",[]).map_err(err)?;c.execute("INSERT OR IGNORE INTO doctor_revisions(id) SELECT id FROM doctors",[]).map_err(err)?;Ok(())}
impl Database{
 pub(crate) fn migrate_doctors(&self,c:&Connection)->Result<(),String>{
  if c.query_row("SELECT value FROM metadata WHERE key='doctor_signatures_v1'",[],|r|r.get::<_,String>(0)).optional().map_err(err)?.is_some(){return Ok(())}
  let backup=self.backup_from(c,&format!("before-signatures-{}.db",chrono::Local::now().format("%Y%m%d-%H%M%S-%f")))?;let tx=c.unchecked_transaction().map_err(err)?;freeze(&tx)?;tx.execute("INSERT INTO metadata VALUES('doctor_signatures_v1',?)",[json!({"backup":backup}).to_string()]).map_err(err)?;tx.commit().map_err(err)
 }
 pub fn doctors(&self)->Result<Value,String>{let c=self.open()?;let sql=if crate::lifecycle::exists(&c,"doctor_revisions")?{"SELECT d.id,d.name,d.hidden,COALESCE(r.revision,1) AS revision FROM doctors d LEFT JOIN doctor_revisions r ON r.id=d.id ORDER BY d.name,d.id"}else{"SELECT id,name,hidden,1 AS revision FROM doctors ORDER BY name,id"};Ok(json!(rows(&c,sql,[])?))}
 pub fn save_doctor(&self,id:Option<i64>,revision:Option<i64>,name:&str,hidden:bool)->Result<i64,String>{
  if name.trim().is_empty()||name.chars().count()>200{return Err("Укажите фамилию и инициалы врача (до 200 символов).".into())}
  let mut c=self.open()?;let tx=c.transaction().map_err(err)?;freeze(&tx)?;
  let key=if let Some(id)=id{let previous=rows(&tx,"SELECT d.*,r.revision FROM doctors d JOIN doctor_revisions r ON r.id=d.id WHERE d.id=?",[id])?.pop().ok_or("Врач не найден")?;
   if previous["revision"].as_i64()!=revision{return Err("Данные врача изменились. Откройте их заново.".into())}
   tx.execute("UPDATE doctors SET name=?,hidden=? WHERE id=?",params![name.trim(),hidden,id]).map_err(err)?;tx.execute("UPDATE doctor_revisions SET revision=revision+1 WHERE id=?",[id]).map_err(err)?;tx.execute("INSERT INTO audit(entity,entity_id,previous_json,saved_at) VALUES('doctor',?,?,datetime('now'))",params![id,previous.to_string()]).map_err(err)?;id
  }else{tx.execute("INSERT INTO doctors(name,hidden) VALUES(?,?)",params![name.trim(),hidden]).map_err(err)?;let id=tx.last_insert_rowid();tx.execute("INSERT INTO doctor_revisions(id) VALUES(?)",[id]).map_err(err)?;id};
  crate::security::audit(&tx,if id.is_some(){"save_doctor"}else{"create_doctor"},key)?;tx.commit().map_err(err)?;Ok(key)
 }
 pub(crate) fn signature(c:&Connection,study:i64,doctor:i64)->Result<Option<String>,String>{if !crate::lifecycle::exists(c,"study_signatures")?{return Ok(None)}c.query_row("SELECT name FROM study_signatures WHERE study_id=? AND doctor_id=?",params![study,doctor],|r|r.get(0)).optional().map_err(err)}
 pub(crate) fn save_signature(c:&Connection,study:i64,doctor:i64)->Result<(),String>{tables(c)?;if Self::signature(c,study,doctor)?.is_some(){return Ok(())}let name=c.query_row("SELECT name FROM doctors WHERE id=?",[doctor],|r|r.get::<_,String>(0)).optional().map_err(err)?.unwrap_or_default();c.execute("INSERT INTO study_signatures VALUES(?,?,?) ON CONFLICT(study_id) DO UPDATE SET doctor_id=excluded.doctor_id,name=excluded.name",params![study,doctor,name]).map_err(err)?;Ok(())}
}

#[cfg(test)]mod tests{
 use super::*;
 fn fixture()->Database{let root=std::env::temp_dir().join(format!("uzi-doctors-{}",chrono::Utc::now().timestamp_nanos_opt().unwrap()));std::fs::create_dir_all(&root).unwrap();let db=Database::new(root.join("uzi.db"));let c=Connection::open(&db.path).unwrap();c.execute_batch(include_str!("../schema.sql")).unwrap();c.execute_batch(include_str!("../extended.sql")).unwrap();c.execute_batch("PRAGMA user_version=2;INSERT INTO patients(id,name,search_name,gender) VALUES(1,'Тест','тест','F');INSERT INTO doctors VALUES(1,'Прежняя подпись',0),(2,'Другой врач',0);INSERT INTO templates VALUES(1,'УЗИ','universal');INSERT INTO studies(id,patient_id,date,template_id,doctor_id,title,conclusion,addition,fields_json,legacy_version,origin,status) VALUES(1,1,'2026-11-08',1,1,'УЗИ','Прежний текст','','{}','1','legacy','legacy:1');INSERT INTO app_users(username,display_name,password_hash,role) VALUES('test','Имя учётной записи','unused','viewer');").unwrap();db}
 fn save(db:&Database,id:Option<i64>,revision:Option<i64>,doctor:i64,source:Option<i64>)->Result<i64,String>{db.save_study(serde_json::from_value(json!({"id":id,"revision":revision,"patientId":1,"templateId":1,"doctorId":doctor,"date":"2026-11-09","conclusion":"Сохранено","addition":"","fields":{},"status":"final","templateVersion":"1","sourceId":source})).unwrap())}
 fn clean(db:Database){std::fs::remove_dir_all(db.path.parent().unwrap()).unwrap()}
 #[test]fn rename_keeps_existing_signatures_and_account_names_and_new_documents_use_new_name(){let db=fixture();let c=db.open().unwrap();db.migrate_doctors(&c).unwrap();db.migrate_doctors(&c).unwrap();assert_eq!(db.backups().unwrap().as_array().unwrap().len(),1);db.save_doctor(Some(1),Some(1),"Новое имя",false).unwrap();assert_eq!(db.study(1).unwrap()["doctor"],"Прежняя подпись");assert_eq!(db.study(1).unwrap()["doctorCurrentName"],"Новое имя");assert!(db.save_doctor(Some(1),Some(1),"Устаревшее",false).is_err());let fresh=save(&db,None,None,1,None).unwrap();assert_eq!(db.study(fresh).unwrap()["doctor"],"Новое имя");let copied=save(&db,None,None,1,Some(1)).unwrap();assert_eq!(db.study(copied).unwrap()["doctor"],"Новое имя");save(&db,Some(1),Some(1),1,None).unwrap();assert_eq!(db.study(1).unwrap()["doctor"],"Прежняя подпись");save(&db,Some(1),Some(2),2,None).unwrap();assert_eq!(db.study(1).unwrap()["doctor"],"Другой врач");let prior:String=c.query_row("SELECT previous_json FROM audit WHERE entity='study' AND entity_id=1 ORDER BY id DESC LIMIT 1",[],|r|r.get(0)).unwrap();assert!(prior.contains("Прежняя подпись"));assert_eq!(c.query_row("SELECT display_name FROM app_users",[],|r|r.get::<_,String>(0)).unwrap(),"Имя учётной записи");drop(c);clean(db)}
 #[test]fn unspecified_legacy_signature_stays_empty_instead_of_inventing_a_printed_name(){let db=fixture();let c=db.open().unwrap();c.execute_batch("INSERT INTO studies(id,patient_id,date,template_id,doctor_id,title,conclusion,addition,fields_json,legacy_version,origin,status) VALUES(2,1,'2001-01-01',1,0,'УЗИ','','','{}','1','legacy','legacy:1')").unwrap();assert!(db.study(2).unwrap()["doctor"].is_null());db.migrate_doctors(&c).unwrap();assert_eq!(db.study(2).unwrap()["doctor"],"");assert_eq!(Database::signature(&c,2,0).unwrap(),Some(String::new()));drop(c);clean(db)}
 #[test]fn hidden_doctor_can_remain_in_existing_native_record_but_not_a_new_assignment(){let db=fixture();let id=save(&db,None,None,1,None).unwrap();db.save_doctor(Some(1),Some(1),"Прежняя подпись",true).unwrap();assert!(save(&db,None,None,1,None).unwrap_err().contains("Скрытый врач"));assert!(save(&db,None,None,1,Some(id)).is_err());save(&db,Some(id),Some(1),1,None).unwrap();assert_eq!(db.study(id).unwrap()["doctor"],"Прежняя подпись");db.save_doctor(Some(1),Some(2),"Возвращённый врач",false).unwrap();assert!(save(&db,None,None,1,None).is_ok());assert_eq!(db.doctors().unwrap().as_array().unwrap().len(),2);clean(db)}
}
